	if value.Type().AssignableTo(target) {
		return value
	}
	if target.Kind() == reflect.Pointer {
		v := reflect.New(target.Elem())
		v.Elem().Set(unicodeMonitorWireAdapt(value, target.Elem()))
		return v
	}
	if value.Kind() == reflect.Pointer && !value.IsNil() {
		return unicodeMonitorWireAdapt(value.Elem(), target)
	}
	if value.Type().ConvertibleTo(target) {
		return value.Convert(target)
	}
	unicodeMonitorFail("lang.golang.input-codec-failed", "a model codec's native type does not match its declaration", nil)
	return reflect.Value{}
